		cellsAndProofs = append(cellsAndProofs, cellsProofs)
	}

	dataColumnSidecars, err := DataColumnSidecars(block, cellsAndProofs)
	if err != nil {
		return nil, errors.Wrap(err, "data column sidcars")
	}

	return dataColumnSidecars, nil
}

